"use client";
/* Buff, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Buff(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("buff"); }, []);
  return React.createElement("piix-pal", { "pal": "buff", ...piixAttrs(props) });
}

export default Buff;
